"""Meridian CRM 4.2 permission-check migration."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform the action on the record."""
    role_id = user.get("ROLE_ID", "")

    matching_rows = (
        row
        for row in role_rows
        if row.get("role_id", "") == role_id
        and row.get("object", "") == object
        and row.get("action", "") == action
    )

    for row in matching_rows:
        # ADMIN bypasses scope only; reaching this point confirms a row exists.
        if role_id == "ADMIN":
            scope_grants = True
        else:
            scope = row.get("scope", "")
            if scope == "ALL":
                scope_grants = True
            elif scope == "TEAM":
                scope_grants = (
                    user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
                )
            elif scope == "OWN":
                scope_grants = (
                    record.get("OWNER_UID", "") == user.get("USR_ID", "")
                )
            else:
                scope_grants = False

        if scope_grants:
            if action == "DELETE":
                del_flg: Any = record.get("DEL_FLG", "")
                if del_flg not in ("", "N"):
                    continue
            return True

    return False
